from pydantic import BaseModel  
from typing import List, Optional, Dict, Any  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy  

class MaxMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data

        # nodes_list is a list of int  
        nodes_list = data['nodes']  
        # edges_list is a list of tuple, where each tuple is (int, int)  
        edges_list = data['edges']  
        # cnt_maximal_cocktails is a int  
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']  

        # return a tuple representing a new edge to add (int, int)  
        new_edge = None
        # TODO: implement your decision logic here  

        for i in range(len(nodes_list)):
            for j in range(i + 1, len(nodes_list)):
                potential_edge = (nodes_list[i], nodes_list[j])
                if potential_edge not in edges_list:
                    temp_edges = edges_list + [potential_edge]

                    # Calculate the number of maximal cocktails with the new edge
                    maximal_cocktails_count = self.calculate_maximal_cocktails(nodes_list, temp_edges)

                    if maximal_cocktails_count >= cnt_maximal_cocktails:
                        new_edge = potential_edge
                        break
            if new_edge is not None:
                break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=new_edge, type='custom')]
        )

    def calculate_maximal_cocktails(self, nodes, edges):
        graph = {node: [] for node in nodes}
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        maximal_cocktails = []
        for i in range(1 << len(nodes)):
            cocktail = []
            for j in range(len(nodes)):
                if (i >> j) & 1:
                    cocktail.append(nodes[j])

            is_independent = True
            for u in cocktail:
                for v in cocktail:
                    if u != v and v in graph[u]:
                        is_independent = False
                        break
                if not is_independent:
                    break

            if is_independent:
                is_maximal = True
                for node in nodes:
                    if node not in cocktail:
                        temp_cocktail = cocktail + [node]
                        temp_independent = True
                        for u in temp_cocktail:
                            for v in temp_cocktail:
                                if u != v and v in graph[u]:
                                    temp_independent = False
                                    break
                            if not temp_independent:
                                break

                        if temp_independent:
                            is_maximal = False
                            break

                if is_maximal:
                    maximal_cocktails.append(tuple(sorted(cocktail)))

        return len(set(maximal_cocktails))

